return $input.all().map(item => {
  // Handle different structures an AI node might output (direct json, or nested text/output)
  let data = item.json;

  // If the AI node outputted the JSON as a string inside another property, parse it
  if (typeof data.output === 'string') {
    try { data = JSON.parse(data.output); } catch (e) {}
  } else if (typeof data.text === 'string') {
    try { data = JSON.parse(data.text); } catch (e) {}
  } else if (typeof data.json === 'object' && data.json !== null) {
    data = data.json;
  }

  // Fallback to empty object if still nothing
  data = data || {};

  // 1. Email Validation & Cleanup
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const rawEmail = data.Email ? String(data.Email).trim() : '';
  const isEmailValid = emailRegex.test(rawEmail);
  const cleanedEmail = isEmailValid ? rawEmail : (data.Email || null);

  // 2. Course Normalization
  let course = data.Course ? String(data.Course).trim() : '';
  if (course && course.toLowerCase() !== 'null') {
    course = course.charAt(0).toUpperCase() + course.slice(1).toLowerCase();
  } else {
    course = '';
  }

  // 3. Phone Number Sanitization
  const phone = data.Phone ? String(data.Phone).replace(/\D/g, '') : '';

  // 4. Date Formatting
  let enrolledDate = null;
  if (data.Enrolled_Date && data.Enrolled_Date !== 'null') {
    const parsedDate = new Date(data.Enrolled_Date);
    if (!isNaN(parsedDate.getTime())) {
      enrolledDate = parsedDate.toISOString().split('T')[0];
    } else {
      enrolledDate = data.Enrolled_Date; // Keep raw string if parsing fails
    }
  }

  // Return the cleaned object structure
  return {
    json: {
      Student_ID: data.Student_ID || data.id || '',
      Name: data.Name || data.student_name || '',
      Email: cleanedEmail,
      Email_Valid: isEmailValid,
      Phone: phone,
      Course: course,
      Fee_Paid: data.Fee_Paid === true || data.Fee_Paid === 'true' || data.Fee_Paid === 1,
      City: data.City || '',
      Enrolled_Date: enrolledDate
    }
  };
});
